$ErrorActionPreference = "Stop"

$root = Get-Location

if (-not (Test-Path (Join-Path $root ".git"))) {
    throw "Run this script from the SakhtYar repository root."
}

function Write-Base64Text([string]$RelativePath, [string]$Base64) {
    $path = Join-Path $root $RelativePath
    $parent = Split-Path $path -Parent

    if (-not (Test-Path $parent)) {
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
    }

    [System.IO.File]::WriteAllBytes(
        $path,
        [Convert]::FromBase64String($Base64)
    )
}

function Write-Base64Binary([string]$RelativePath, [string]$Base64) {
    $path = Join-Path $root $RelativePath
    $parent = Split-Path $path -Parent

    if (-not (Test-Path $parent)) {
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
    }

    [System.IO.File]::WriteAllBytes(
        $path,
        [Convert]::FromBase64String($Base64)
    )
}

function Read-Utf8([string]$Path) {
    return [System.IO.File]::ReadAllText(
        $Path,
        (New-Object System.Text.UTF8Encoding($false))
    )
}

function Write-Utf8([string]$Path, [string]$Content) {
    [System.IO.File]::WriteAllText(
        $Path,
        $Content,
        (New-Object System.Text.UTF8Encoding($false))
    )
}

Write-Host ""
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host " SakhtYar - Approved Theme Exact-Style Repair" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host ""

# -------------------------------------------------------------------------
# Backup touched files.
# -------------------------------------------------------------------------
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $root ".local\patch-backups\approved-theme-$stamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$textFiles = @{}
$textFiles["frontend/src/ui/presentation.ts"] = ""
$textFiles["frontend/src/app/AppShell.tsx"] = ""
$textFiles["frontend/src/pages/LoginPage.tsx"] = ""
$textFiles["frontend/src/pages/CasesPage.tsx"] = ""
$textFiles["frontend/src/pages/UsersPage.tsx"] = ""
$textFiles["frontend/src/pages/AccountPage.tsx"] = ""
$textFiles["frontend/src/pages/CaseDetailPage.tsx"] = ""
$textFiles["frontend/src/styles/global.css"] = ""
$textFiles["frontend/src/ui/antdTheme.ts"] = ""
$textFiles["backend/modules/identity/src/main/java/com/sakhtyar/identity/application/AdminBootstrap.java"] = ""

$binaryFiles = @{}
$binaryFiles["frontend/public/assets/sakhtyar/login-construction.jpg"] = ""
$binaryFiles["frontend/public/assets/sakhtyar/hero-construction.jpg"] = ""
$binaryFiles["frontend/public/assets/sakhtyar/projects/project-01.jpg"] = ""
$binaryFiles["frontend/public/assets/sakhtyar/projects/project-02.jpg"] = ""
$binaryFiles["frontend/public/assets/sakhtyar/projects/project-03.jpg"] = ""

Write-Host "[1/8] Backing up current source..." -ForegroundColor Cyan

foreach ($relativePath in $textFiles.Keys) {
    $source = Join-Path $root $relativePath

    if (Test-Path $source) {
        $backup = Join-Path $backupRoot $relativePath
        $backupParent = Split-Path $backup -Parent
        New-Item -ItemType Directory -Force -Path $backupParent | Out-Null
        Copy-Item $source $backup -Force
    }
}

Write-Host "  Backup: $backupRoot" -ForegroundColor DarkGray

# -------------------------------------------------------------------------
# Write local imagery extracted from the APPROVED mockups.
# No remote Unsplash dependency.
# -------------------------------------------------------------------------
Write-Host ""
Write-Host "[2/8] Installing local approved-theme imagery..." -ForegroundColor Cyan

foreach ($relativePath in $binaryFiles.Keys) {
    Write-Base64Binary $relativePath $binaryFiles[$relativePath]
    Write-Host ("  asset: " + $relativePath) -ForegroundColor DarkGreen
}

# -------------------------------------------------------------------------
# Write redesigned UI.
# -------------------------------------------------------------------------
Write-Host ""
Write-Host "[3/8] Applying approved UI theme..." -ForegroundColor Cyan

foreach ($relativePath in $textFiles.Keys) {
    Write-Base64Text $relativePath $textFiles[$relativePath]
    Write-Host ("  updated: " + $relativePath) -ForegroundColor DarkGreen
}

# -------------------------------------------------------------------------
# Normalize config fallback display-name, but never expose secrets.
# -------------------------------------------------------------------------
Write-Host ""
Write-Host "[4/8] Normalizing bootstrap display name..." -ForegroundColor Cyan

$appYmlPath = Join-Path $root "backend\app\src\main\resources\application.yml"

if (Test-Path $appYmlPath) {
    $appYml = Read-Utf8 $appYmlPath

    $appYml = [regex]::Replace(
        $appYml,
        '(?m)^\s{4}display-name:\s*\$\{APP_BOOTSTRAP_ADMIN_DISPLAY_NAME:[^}]*\}\s*$',
        '    display-name: ${APP_BOOTSTRAP_ADMIN_DISPLAY_NAME:System Administrator}'
    )

    $appYml = $appYml.Replace(
        "http://localhost:5173,http://localhost:5174,http://localhost:3000",
        "http://localhost:5175,http://localhost:5173,http://localhost:5174,http://localhost:3000"
    )

    Write-Utf8 $appYmlPath $appYml
}

# -------------------------------------------------------------------------
# Make seeded demo project cover URLs local for future starts.
# UI already has a local fallback for current DB rows.
# -------------------------------------------------------------------------
Write-Host ""
Write-Host "[5/8] Updating development seed image URLs..." -ForegroundColor Cyan

$seedPath = Join-Path $root "backend\app\src\main\resources\db\dev\seed-demo.sql"

if (Test-Path $seedPath) {
    $seed = Read-Utf8 $seedPath

    $remoteUrls = [regex]::Matches(
        $seed,
        'https://images\.unsplash\.com/[^'']+'
    ) | ForEach-Object { $_.Value } | Select-Object -Unique

    $i = 0
    foreach ($url in $remoteUrls) {
        $localNumber = ($i % 3) + 1
        $localUrl = "/assets/sakhtyar/projects/project-0$localNumber.jpg"
        $seed = $seed.Replace($url, $localUrl)
        $i++
    }

    Write-Utf8 $seedPath $seed
    Write-Host "  seed-demo.sql now uses local cover assets." -ForegroundColor Green
} else {
    Write-Host "  seed-demo.sql not found; skipped. UI fallback still works." -ForegroundColor Yellow
}

# -------------------------------------------------------------------------
# Keep local backup directory ignored.
# -------------------------------------------------------------------------
Write-Host ""
Write-Host "[6/8] Updating .gitignore..." -ForegroundColor Cyan

$gitignorePath = Join-Path $root ".gitignore"
$gitignore = if (Test-Path $gitignorePath) {
    Get-Content $gitignorePath -Raw
} else {
    ""
}

$entry = "/.local/patch-backups/"
if ($gitignore -notmatch [regex]::Escape($entry)) {
    $gitignore += "`r`n$entry"
}

Write-Utf8 $gitignorePath ($gitignore.Trim() + "`r`n")

# -------------------------------------------------------------------------
# Build frontend.
# -------------------------------------------------------------------------
Write-Host ""
Write-Host "[7/8] Building frontend..." -ForegroundColor Cyan

Push-Location (Join-Path $root "frontend")
try {
    npm run build

    if ($LASTEXITCODE -ne 0) {
        throw "Frontend build failed."
    }
}
finally {
    Pop-Location
}

# -------------------------------------------------------------------------
# Compile backend.
# -------------------------------------------------------------------------
Write-Host ""
Write-Host "[8/8] Compiling backend..." -ForegroundColor Cyan

Push-Location (Join-Path $root "backend")
try {
    mvn -q -pl app -am -DskipTests compile

    if ($LASTEXITCODE -ne 0) {
        throw "Backend compile failed."
    }
}
finally {
    Pop-Location
}

git diff --check
if ($LASTEXITCODE -ne 0) {
    throw "git diff --check failed."
}

Write-Host ""
Write-Host "============================================================" -ForegroundColor Green
Write-Host " DONE" -ForegroundColor Green
Write-Host "============================================================" -ForegroundColor Green
Write-Host ""
Write-Host "Important findings fixed:" -ForegroundColor Cyan
Write-Host " - Approved mockup imagery is now LOCAL under frontend/public/assets/sakhtyar"
Write-Host " - No runtime dependency on Unsplash for the approved backgrounds/cards"
Write-Host " - Login is now the split architectural design from the approved mockup"
Write-Host " - Cases hero + statistic cards + project photos match the approved theme"
Write-Host " - Users page now uses the same hero/theme/table language"
Write-Host " - Account page was previously untouched; it is now redesigned too"
Write-Host " - Corrupted admin display-name is guarded in UI and safely synchronized on backend startup"
Write-Host " - Case detail uses local project imagery while preserving the working map"
Write-Host ""
Write-Host "Next:" -ForegroundColor Yellow
Write-Host "  1) Stop backend and frontend"
Write-Host "  2) Run SakhtYarApplication again"
Write-Host "  3) Run frontend: npm run dev"
Write-Host "  4) Set Chrome zoom to 100% (your screenshot showed 80%)"
Write-Host "  5) Ctrl+F5"
Write-Host "  6) Open: http://localhost:5175/cases"
